const STORAGE_KEY = "budget-app-v1";
const APP_VERSION = 6;
const LOGO_VERSION = 4;
const DEFAULT_LOGO_SRC = "data:image/jpeg;base64,";

const defaults = {
  companyTitle: "GC",
  companySubtitle: "CARPINTERIA METALICA",
  companyName: "GonzÃ¡lez e Hijos, S. L.",
  companyAddress: "VILAPISCINA, 20 - 22\nTelf. 93 429 38 50\n93 420 61 70\n08031 BARCELONA",
  docType: "PRESUPUESTO",
  docNumber: "61636",
  docDate: "2026-03-24",
  reference: "REBLA PRINCIPAL 108",
  clientName: "CREATE INTERIORS",
  clientPhone: "",
  clientTaxId: "",
  clientInfo: "-",
  taxRate: 21,
  discountRate: 0,
  dueDate: "2026-05-21",
  paymentMethod: "TRANSFERENCIA IBAN ES15",
  bankEntity: "0182",
  bankOffice: "4597",
  bankControl: "11",
  bankAccount: "0200263383",
  companyTaxId: "B-59951038",
  footerNote: "Presupuesto recibido antes de realizar los trabajos.",
  appVersion: APP_VERSION,
  logoData: "",
  logoVersion: LOGO_VERSION,
  nextNumbers: {
    PRESUPUESTO: 61637,
    FACTURA: 26083
  },
  items: [
    {
      description:
        "FabricaciÃ³n y colocaciÃ³n de puerta de una hoja practicable, con CERRADURA DE TRES PUNTOS CON BOMBIN INTERIOR LLAVE DE PUNTOS. En carpinterÃ­a de aluminio serie OPTIMA 65 con ROTURA DE PUENTE TERMICO. Color: LACADO BLANCO. Medidas: 2100 mm. de alto por 930 mm. de ancho. Acristalamiento con CLIMALIT 4 BAJO EMISIVO CONTROL SOLAR/16/4+4 LAMINAR DE SEGURIDAD. Con persiana de aluminio incorporada MONOBLOC accionada con motor con mando.\n**NOTA**\n********\nINCREMENTO POR INSTALACION PERSIANA AUTOBLOCANTE 890+\nIVA",
      quantity: 1,
      price: 2120
    }
  ]
};

let state = loadState();

const form = document.querySelector("#quoteForm");
const itemsEl = document.querySelector("#items");
const itemTemplate = document.querySelector("#itemTemplate");
const logoInput = document.querySelector("#logoInput");
const defaultLogoBtn = document.querySelector("#defaultLogoBtn");
const sampleBtn = document.querySelector("#sampleBtn");

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function normalizeState(raw) {
  raw = raw || {};
  if (raw.appVersion !== APP_VERSION) {
    const reset = clone(defaults);
    reset.nextNumbers = { ...defaults.nextNumbers, ...(raw.nextNumbers || {}) };
    return reset;
  }
  const merged = { ...defaults, ...raw };
  if (raw.logoVersion !== LOGO_VERSION) {
    merged.logoData = "";
  }
  merged.logoVersion = LOGO_VERSION;
  merged.nextNumbers = { ...defaults.nextNumbers, ...(raw.nextNumbers || {}) };
  merged.items = Array.isArray(raw.items) && raw.items.length ? raw.items : clone(defaults.items);
  return merged;
}

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return saved ? normalizeState(saved) : clone(defaults);
  } catch {
    return clone(defaults);
  }
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function formatMoney(value) {
  return new Intl.NumberFormat("es-ES", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(value);
}

function formatDate(value) {
  if (!value) return "";
  const [year, month, day] = value.split("-");
  return `${day}-${month}-${year}`;
}

function getDocumentFileName() {
  const prefix = state.docType === "FACTURA" ? "FRA" : "P";
  const number = String(state.docNumber || "nuevo").trim() || "nuevo";
  const cleanNumber = number.replace(/[\\/:*?"<>|]+/g, "-").replace(/\s+/g, "-");
  return `${prefix}-${cleanNumber}`;
}

function getBaseUrl() {
  const path = window.location.href.replace(/[^/]*$/, "");
  return path;
}

function fillForm() {
  Object.entries(state).forEach(([key, value]) => {
    const field = form.elements[key];
    if (field && key !== "items" && key !== "logoData") field.value = value;
  });
  renderItemsEditor();
  renderPreview();
}

function syncItemsFromEditor() {
  const rows = Array.from(itemsEl.querySelectorAll(".item-row"));
  if (!rows.length) return;
  state.items = rows.map((row) => ({
    description: row.querySelector('[data-field="description"]').value || "",
    quantity: Number(row.querySelector('[data-field="quantity"]').value) || 0,
    price: Number(row.querySelector('[data-field="price"]').value) || 0
  }));
}

function readForm() {
  const data = new FormData(form);
  syncItemsFromEditor();
  state = {
    ...state,
    companyTitle: data.get("companyTitle") || "",
    companySubtitle: data.get("companySubtitle") || "",
    companyName: data.get("companyName") || "",
    companyAddress: data.get("companyAddress") || "",
    docType: data.get("docType") || "PRESUPUESTO",
    docNumber: data.get("docNumber") || "",
    docDate: data.get("docDate") || "",
    reference: data.get("reference") || "",
    clientName: data.get("clientName") || "",
    clientPhone: data.get("clientPhone") || "",
    clientTaxId: data.get("clientTaxId") || "",
    clientInfo: data.get("clientInfo") || "",
    taxRate: Number(data.get("taxRate")) || 0,
    discountRate: Number(data.get("discountRate")) || 0,
    dueDate: data.get("dueDate") || "",
    paymentMethod: data.get("paymentMethod") || "",
    bankEntity: data.get("bankEntity") || "",
    bankOffice: data.get("bankOffice") || "",
    bankControl: data.get("bankControl") || "",
    bankAccount: data.get("bankAccount") || "",
    companyTaxId: data.get("companyTaxId") || "",
  };
  syncNextNumber();
  saveState();
  renderPreview();
}

function syncNextNumber() {
  const type = state.docType || "PRESUPUESTO";
  const current = Number.parseInt(String(state.docNumber).replace(/\D/g, ""), 10);
  if (!Number.isNaN(current) && current >= (state.nextNumbers[type] || 1)) {
    state.nextNumbers[type] = current + 1;
  }
}

function renderItemsEditor() {
  itemsEl.replaceChildren();
  state.items.forEach((item, index) => {
    const node = itemTemplate.content.firstElementChild.cloneNode(true);
    node.querySelector('[data-field="description"]').value = item.description || "";
    node.querySelector('[data-field="quantity"]').value = item.quantity == null ? 1 : item.quantity;
    node.querySelector('[data-field="price"]').value = item.price == null ? 0 : item.price;
    node.querySelectorAll("[data-field]").forEach((field) => {
      field.addEventListener("input", () => {
        const key = field.dataset.field;
        state.items[index][key] = key === "description" ? field.value : Number(field.value) || 0;
        saveState();
        renderPreview();
      });
    });
    node.querySelector(".remove-item").addEventListener("click", () => {
      state.items.splice(index, 1);
      if (!state.items.length) state.items.push({ description: "", quantity: 1, price: 0 });
      saveState();
      renderItemsEditor();
      renderPreview();
    });
    itemsEl.append(node);
  });
}

function setText(id, value) {
  document.querySelector(`#${id}`).textContent = value == null ? "" : value;
}

function renderLogo() {
  const logo = document.querySelector("#logoPreview");
  const brand = document.querySelector(".brand");
  logo.replaceChildren();
  logo.classList.add("has-image");
  logo.classList.add("full-logo");
  brand.classList.add("full-logo");
  const img = document.createElement("img");
  img.alt = state.companyName || "Logotipo";
  if (state.logoData) {
    img.src = state.logoData;
    logo.append(img);
  } else {
    img.src = DEFAULT_LOGO_SRC;
    logo.append(img);
  }
}

function renderPreview() {
  renderLogo();
  const docType = state.docType.toUpperCase();
  setText("companySubtitlePreview", state.companySubtitle);
  setText("companyNamePreview", state.companyName);
  setText("companyAddressPreview", state.companyAddress);
  setText("docTypePreview", docType);
  setText("docTypeInlinePreview", docType);
  setText("docNumberPreview", state.docNumber);
  setText("docDatePreview", formatDate(state.docDate));
  setText("referencePreview", state.reference);
  setText("clientNamePreview", state.clientName);
  setText("clientPhonePreview", state.clientPhone);
  setText("clientTaxIdPreview", state.clientTaxId);
  setText("clientInfoPreview", state.clientInfo);
  setText("footerNotePreview", state.footerNote);
  setText("taxRatePreview", formatMoney(state.taxRate).replace(",00", ""));
  document.querySelector("#clientTaxWrap").hidden = docType !== "FACTURA" && !state.clientTaxId;
  document.querySelector("#budgetFooter").hidden = docType === "FACTURA";
  document.querySelector("#invoiceFooter").hidden = docType !== "FACTURA";

  const tbody = document.querySelector("#linesPreview");
  tbody.replaceChildren();

  let subtotal = 0;
  state.items.forEach((item) => {
    const quantity = Number(item.quantity) || 0;
    const price = Number(item.price) || 0;
    const amount = quantity * price;
    subtotal += amount;

    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td class="concept-cell"></td>
      <td class="num">${quantity ? formatMoney(quantity).replace(",00", "") : ""}</td>
      <td class="num">${price ? formatMoney(price) : ""}</td>
      <td class="num">${amount ? formatMoney(amount) : ""}</td>
    `;
    tr.querySelector(".concept-cell").textContent = item.description || "";
    tbody.append(tr);
  });

  const tax = subtotal * (Number(state.taxRate) || 0) / 100;
  const total = subtotal + tax;
  setText("subtotalPreview", `${formatMoney(subtotal)} Euros`);
  setText("taxPreview", `${formatMoney(tax)} Euros`);
  setText("totalPreview", `${formatMoney(total)} Euros`);

  const discount = subtotal * (Number(state.discountRate) || 0) / 100;
  const base = subtotal - discount;
  const invoiceTax = base * (Number(state.taxRate) || 0) / 100;
  const invoiceTotal = base + invoiceTax;
  setText("invoiceSubtotalPreview", formatMoney(subtotal));
  setText("discountRatePreview", formatMoney(state.discountRate).replace(",00", ""));
  setText("discountPreview", formatMoney(discount));
  setText("basePreview", formatMoney(base));
  setText("invoiceTaxRatePreview", formatMoney(state.taxRate).replace(",00", ""));
  setText("invoiceTaxPreview", formatMoney(invoiceTax));
  setText("invoiceTotalPreview", `${formatMoney(invoiceTotal)} Euros`);
  setText("dueDatePreview", formatDate(state.dueDate));
  setText("paymentMethodPreview", state.paymentMethod);
  setText("bankEntityPreview", state.bankEntity);
  setText("bankOfficePreview", state.bankOffice);
  setText("bankControlPreview", state.bankControl);
  setText("bankAccountPreview", state.bankAccount);
  setText("companyTaxIdPreview", state.companyTaxId ? `NIF ${state.companyTaxId}` : "");
}

form.addEventListener("input", readForm);
form.addEventListener("change", readForm);

logoInput.addEventListener("change", () => {
  const file = logoInput.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.addEventListener("load", () => {
    state.logoData = reader.result;
    state.logoVersion = LOGO_VERSION;
    saveState();
    renderPreview();
  });
  reader.readAsDataURL(file);
});

defaultLogoBtn.addEventListener("click", () => {
  state.logoData = "";
  state.logoVersion = LOGO_VERSION;
  logoInput.value = "";
  saveState();
  renderPreview();
});

sampleBtn.addEventListener("click", () => {
  const nextNumbers = state.nextNumbers || clone(defaults.nextNumbers);
  state = {
    ...clone(defaults),
    nextNumbers
  };
  saveState();
  fillForm();
});

document.querySelector("#addItemBtn").addEventListener("click", () => {
  state.items.push({ description: "", quantity: 1, price: 0 });
  saveState();
  renderItemsEditor();
  renderPreview();
});

document.querySelector("#newDocBtn").addEventListener("click", () => {
  const type = state.docType || "PRESUPUESTO";
  const nextNumber = state.nextNumbers && state.nextNumbers[type] ? state.nextNumbers[type] : 1;
  state = {
    ...state,
    docNumber: String(nextNumber),
    docDate: new Date().toISOString().slice(0, 10),
    reference: "",
    clientName: "",
    clientPhone: "",
    clientTaxId: "",
    clientInfo: "",
    items: [{ description: "", quantity: 1, price: 0 }],
    nextNumbers: {
      ...state.nextNumbers,
      [type]: nextNumber + 1
    }
  };
  saveState();
  fillForm();
});

document.querySelector("#backupBtn").addEventListener("click", () => {
  const data = JSON.stringify({ exportedAt: new Date().toISOString(), app: "presupuestos-facturas", state }, null, 2);
  const blob = new Blob([data], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `backup-presupuestos-${new Date().toISOString().slice(0, 10)}.json`;
  document.body.append(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
});

document.querySelector("#restoreBtn").addEventListener("click", () => {
  document.querySelector("#restoreInput").click();
});

document.querySelector("#restoreInput").addEventListener("change", (event) => {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.addEventListener("load", () => {
    try {
      const parsed = JSON.parse(reader.result);
      state = normalizeState(parsed.state || parsed);
      saveState();
      fillForm();
    } catch {
      alert("No se ha podido leer el backup JSON.");
    } finally {
      event.target.value = "";
    }
  });
  reader.readAsText(file);
});

document.querySelector("#printBtn").addEventListener("click", () => {
  readForm();
  const fileName = getDocumentFileName();
  document.title = fileName;
  const printWindow = window.open("", "_blank");
  if (!printWindow) {
    alert("El navegador ha bloqueado la ventana de impresiÃ³n. Permite ventanas emergentes para esta web o usa el menÃº del navegador para imprimir/guardar PDF.");
    return;
  }
  printWindow.document.open();
  printWindow.document.write(`<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <base href="${getBaseUrl()}">
  <title>${fileName}</title>
  <link rel="stylesheet" href="styles.css?v=6">
  <style>
    @page { size: A4; margin: 0; }
    body { background: #fff; }
    .print-toolbar { display: flex; justify-content: center; gap: 8px; padding: 12px; }
    .sheet { box-shadow: none; margin: 0 auto; }
    @media print { .print-toolbar { display: none; } }
  </style>
</head>
<body>
  <div class="print-toolbar">
    <button type="button" onclick="window.print()">Imprimir / PDF</button>
  </div>
  ${document.querySelector("#printArea").outerHTML}
</body>
</html>`);
  printWindow.document.close();
  if (typeof printWindow.print === "function") {
    window.setTimeout(() => {
      printWindow.focus();
      printWindow.print();
    }, 700);
  } else {
    alert("Este navegador no permite imprimir desde la app. Usa Compartir o el menÃº del navegador para imprimir/guardar PDF.");
  }
});

saveState();
fillForm();

